        var w = /^[@$]?[A-Za-z_][A-Za-z0-9_$]*/.exec(code.slice(i))[0];
        var next = code.slice(i + w.length).match(/^\s*(\()/);
        var lw = w.toLowerCase();
        if (kw[sql ? lw : w] || (sql && kw[lw])) wrap("keyword", w);
        else if (w.charAt(0) === "$" || w.charAt(0) === "@") wrap("variable", w);
