    "composer-model": function (node) {
      openComposerPopover("model", node, state.view === "home" ? "home" : "chat");
    },

    "composer-rail": function (node) {
      AI.modelRail = node.dataset.value || "";
      AI.modelQuery = "";
      paintComposerPopover();
    },

    "composer-model-set": function (node) {
      var provider = node.dataset.provider || "";
      var model = node.dataset.value || "";
      var target = AI.popover && AI.popover.target;
      if (target === "provider") {
        closeComposerPopover();
        setProviderModel(provider, model);
        return;
      }
      if (target === "role") {
        var pick = AI.popover && AI.popover.pick;
        closeComposerPopover();
        if (pick) pick(provider, model);
        return;
      }
      AI.pickProvider = provider;
      AI.pickModel = model;
      closeComposerPopover();
      if (AI.thread) {
        AI.thread.provider_id = provider;
        AI.thread.model = model;
        run("chat.update", { thread: AI.thread.id, provider: provider, model: model }, { quiet: true })
          .then(function () { return pollThread(false); })
          .then(function () { renderAssistant(); });
      } else if (state.view === "home") {
        renderHome();
      } else {
        renderAssistant();
      }
    },

    "composer-refresh-models": function () {
      var rail = AI.modelRail;
      if (!rail) return;
      AI.modelFetched[rail] = undefined;
      delete AI.modelError[rail];
      ensureProviderModels(rail, true);
      paintComposerPopover();
    },

    "composer-custom-model": function (node) {
      var rail = AI.modelRail;
      var model = (node.dataset.value || "").trim();
      var target = AI.popover && AI.popover.target;
      var pick = AI.popover && AI.popover.pick;
      if (!rail || !model) return;
      run("provider.model_add", { id: rail, model: model }).then(function (o) {
        if (!o) return null;
        return loadProviders();
      }).then(function () {
        if (target === "provider") {
          closeComposerPopover();
          setProviderModel(rail, model);
          return;
        }
        if (target === "role") {
          closeComposerPopover();
          if (pick) pick(rail, model);
          return;
        }
        AI.pickProvider = rail;
        AI.pickModel = model;
        closeComposerPopover();
        if (AI.thread) {
          AI.thread.provider_id = rail;
          AI.thread.model = model;
          return run("chat.update", { thread: AI.thread.id, provider: rail, model: model }, { quiet: true })
            .then(function () { return pollThread(false); })
            .then(function () { renderAssistant(); });
        }
        if (state.view === "home") renderHome(); else renderAssistant();
      });
    },

