      var id = node.dataset.upload;
      uploadBlob(id).then(function (url) {
        if (!url) return toast("warn", "That picture is no longer stored. Uploads are kept for 30 days.");
        uiSheet(id, '<img class="attach-full" src="' + attr(url) + '" alt="">');
      });
