      run("service.start", { name: "mariadb" }).then(function (outcome) {
        if (!outcome) return null;
        OPS.error = "";
        OPS.errorTab = "";
        OPS.data.db = null;
        return loadServer();
      }).then(function () { return opsLoad("db"); }).then(render);
